//! Source-owned shadcn-style Badge for Dioxus.

use dioxus::prelude::*;

use crate::adico_lib::cn::cn;
use crate::adico_lib::variants::{Radius, Tone};

/// The shape/structure of a [`Badge`], independent of its [`Tone`] color
/// (`BadgeProps::color`). `Destructive` and `Verified` are not shapes --
/// reach the same looks via `variant: Primary, color: Tone::Error` and
/// `variant: Primary, color: Tone::Success` respectively.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum BadgeVariant {
    /// Filled, solid surface.
    #[default]
    Primary,
    /// Muted filled surface.
    Secondary,
    /// Bordered, unfilled surface.
    Outline,
    /// Transparent-until-hover surface.
    Ghost,
    /// Inline semantic-link styling, while remaining a native `<span>`.
    Link,
}

impl BadgeVariant {
    /// Structural classes this shape owns beyond its color, factored out of
    /// [`Tone`]'s shared per-shape methods. `Badge`'s base class always sets
    /// `border`, so every shape except `Outline` needs `border-transparent`
    /// to hide it.
    fn shape_extra_class(self) -> &'static str {
        match self {
            Self::Outline => "",
            Self::Primary | Self::Secondary | Self::Ghost | Self::Link => "border-transparent",
        }
    }

    fn color_class(self, color: Tone) -> &'static str {
        match self {
            Self::Primary => color.solid_class(),
            Self::Secondary => color.soft_class(),
            Self::Outline => color.outline_class(),
            Self::Ghost => color.ghost_class(),
            Self::Link => color.link_class(),
        }
    }
}

/// Props for [`Badge`].
#[derive(Props, Clone, PartialEq)]
pub struct BadgeProps {
    /// Shape/structure of the badge, independent of `color`.
    #[props(default)]
    pub variant: BadgeVariant,
    /// Semantic color, independent of `variant`. `Tone::Default` renders
    /// `variant`'s exact pre-existing look (except `Outline`; see
    /// `registry/lib/variants.rs`'s `Tone::outline_class` doc comment); any
    /// other value recolors it.
    #[props(default)]
    pub color: Tone,
    /// Corner radius of the badge pill.
    #[props(default = Radius::Md)]
    pub radius: Radius,
    /// Extra classes appended to the semantic default.
    #[props(default)]
    pub class: Option<String>,
    /// Native span/global attributes, including ARIA labels and event handlers.
    #[props(extends = GlobalAttributes)]
    #[props(extends = span)]
    pub attributes: Vec<Attribute>,
    /// Caller-composed badge content.
    pub children: Element,
}

/// A small status/label pill with the default adico/shadcn visual language.
#[component]
pub fn Badge(props: BadgeProps) -> Element {
    let class = cn(&[
        "inline-flex items-center border px-2.5 py-0.5 text-xs font-semibold transition-colors focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2",
        props.variant.shape_extra_class(),
        props.variant.color_class(props.color),
        props.radius.class(),
        props.class.as_deref().unwrap_or_default(),
    ]);
    rsx! {
        span { class, ..props.attributes, {props.children} }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_shape_has_a_distinct_default_color_class() {
        assert!(
            BadgeVariant::Primary
                .color_class(Tone::Default)
                .contains("bg-primary")
        );
        assert!(
            BadgeVariant::Secondary
                .color_class(Tone::Default)
                .contains("bg-secondary")
        );
        assert!(
            BadgeVariant::Outline
                .color_class(Tone::Default)
                .contains("border")
        );
    }

    #[test]
    fn removed_destructive_shape_is_reachable_via_color() {
        let class = BadgeVariant::Primary.color_class(Tone::Error);
        assert!(class.contains("bg-destructive"));
        assert!(class.contains("text-destructive-foreground"));
    }

    #[test]
    fn removed_verified_shape_is_reachable_via_color() {
        // Reverses a previously deliberate hardcode -- see
        // statics/styling_usage/badge.json's updated rationale.
        let class = BadgeVariant::Primary.color_class(Tone::Success);
        assert!(class.contains("bg-success"));
        assert!(!class.contains("emerald"));
    }

    #[test]
    fn every_shape_recolors_with_a_non_default_tone() {
        for variant in [
            BadgeVariant::Primary,
            BadgeVariant::Secondary,
            BadgeVariant::Outline,
            BadgeVariant::Ghost,
            BadgeVariant::Link,
        ] {
            assert!(variant.color_class(Tone::Success).contains("success"));
            assert!(variant.color_class(Tone::Warning).contains("warning"));
            assert!(variant.color_class(Tone::Error).contains("destructive"));
            assert!(variant.color_class(Tone::Info).contains("info"));
        }
    }
}

//! Source-owned shadcn-style Breadcrumb for Dioxus.

use dioxus::prelude::*;

use adico_primitives::icons::{ChevronRight, Ellipsis};

use crate::adico_lib::cn::cn;

/// The `<nav aria-label="breadcrumb">` root.
#[component]
pub fn Breadcrumb(class: Option<String>, children: Element) -> Element {
    rsx! {
        nav { "aria-label": "breadcrumb", class: class.unwrap_or_default(), {children} }
    }
}

/// The ordered list of [`BreadcrumbItem`]s.
#[component]
pub fn BreadcrumbList(class: Option<String>, children: Element) -> Element {
    let class = cn(&[
        "flex flex-wrap items-center gap-1.5 text-sm text-muted-foreground break-words sm:gap-2.5",
        class.as_deref().unwrap_or_default(),
    ]);
    rsx! {
        ol { class, {children} }
    }
}

/// A single breadcrumb entry, wrapping a [`BreadcrumbLink`] or
/// [`BreadcrumbPage`].
#[component]
pub fn BreadcrumbItem(class: Option<String>, children: Element) -> Element {
    let class = cn(&[
        "inline-flex items-center gap-1.5",
        class.as_deref().unwrap_or_default(),
    ]);
    rsx! {
        li { class, {children} }
    }
}

/// Props for [`BreadcrumbLink`].
#[derive(Props, Clone, PartialEq)]
pub struct BreadcrumbLinkProps {
    /// The link target.
    #[props(default)]
    pub href: Option<String>,
    /// Extra classes appended to the semantic default.
    #[props(default)]
    pub class: Option<String>,
    /// Native anchor/global attributes.
    #[props(extends = GlobalAttributes)]
    #[props(extends = a)]
    pub attributes: Vec<Attribute>,
    pub children: Element,
}

/// A navigable breadcrumb entry.
#[component]
pub fn BreadcrumbLink(props: BreadcrumbLinkProps) -> Element {
    let class = cn(&[
        "transition-colors hover:text-foreground",
        props.class.as_deref().unwrap_or_default(),
    ]);
    rsx! {
        a { class, href: props.href, ..props.attributes, {props.children} }
    }
}

/// The current (non-navigable) breadcrumb entry.
#[component]
pub fn BreadcrumbPage(class: Option<String>, children: Element) -> Element {
    let class = cn(&[
        "font-normal text-foreground",
        class.as_deref().unwrap_or_default(),
    ]);
    rsx! {
        span {
            class,
            role: "link",
            "aria-disabled": "true",
            "aria-current": "page",
            {children}
        }
    }
}

/// A separator between breadcrumb entries. Defaults to a chevron when no
/// children are supplied.
#[component]
pub fn BreadcrumbSeparator(class: Option<String>, children: Option<Element>) -> Element {
    let class = cn(&["[&>svg]:size-3.5", class.as_deref().unwrap_or_default()]);
    rsx! {
        li {
            role: "presentation",
            "aria-hidden": "true",
            class,
            {children.unwrap_or_else(|| rsx! { ChevronRight {} })}
        }
    }
}

/// A collapsed-run indicator (`...`) for long breadcrumb trails.
///
/// Renders the Lucide `Ellipsis` icon (this icon set's current name for
/// upstream shadcn's `MoreHorizontalIcon`, which Lucide itself renamed).
#[component]
pub fn BreadcrumbEllipsis(class: Option<String>) -> Element {
    let class = cn(&[
        "flex size-9 items-center justify-center",
        class.as_deref().unwrap_or_default(),
    ]);
    rsx! {
        span { role: "presentation", "aria-hidden": "true", class,
            Ellipsis { class: "size-4" }
            span { class: "sr-only", "More" }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn list_uses_a_muted_semantic_surface() {
        let class = cn(&[
            "flex flex-wrap items-center gap-1.5 text-sm text-muted-foreground break-words sm:gap-2.5",
        ]);
        assert!(class.contains("text-muted-foreground"));
    }

    #[test]
    fn current_page_uses_the_foreground_token() {
        let class = cn(&["font-normal text-foreground"]);
        assert!(class.contains("text-foreground"));
    }
}

documentation.usage:
Breadcrumb {
    BreadcrumbList {
        BreadcrumbItem { BreadcrumbLink { href: "/", "Home" } }
        BreadcrumbSeparator {}
        BreadcrumbItem { BreadcrumbPage { "Current" } }
    }
}

