//! Source-owned shadcn-style Checkbox for Dioxus, backed by the owned adico
//! primitive layer.

use dioxus::prelude::*;

pub use adico_primitives::checkbox::CheckboxState;
use adico_primitives::checkbox::{
    Checkbox as CheckboxPrimitive, CheckboxIndicator as CheckboxIndicatorPrimitive,
};
use adico_primitives::icons::Check;

use crate::adico_lib::cn::cn;

/// Props for [`Checkbox`].
#[derive(Props, Clone, PartialEq)]
pub struct CheckboxProps {
    /// The controlled state of the checkbox.
    #[props(default)]
    pub checked: ReadSignal<Option<CheckboxState>>,
    /// The default state when uncontrolled.
    #[props(default = CheckboxState::Unchecked)]
    pub default_checked: CheckboxState,
    /// Whether the checkbox is disabled.
    #[props(default)]
    pub disabled: ReadSignal<bool>,
    /// Whether the checkbox is required in a form.
    #[props(default)]
    pub required: ReadSignal<bool>,
    /// The name of the checkbox, used in forms.
    #[props(default)]
    pub name: ReadSignal<String>,
    /// The value submitted with the checkbox's form, used in forms.
    #[props(default = ReadSignal::new(Signal::new(String::from("on"))))]
    pub value: ReadSignal<String>,
    /// Callback fired when the checked state changes.
    #[props(default)]
    pub on_checked_change: Callback<CheckboxState>,
    /// Extra classes appended to the semantic default.
    #[props(default)]
    pub class: Option<String>,
    /// Accessible label, since the checkbox itself has no visible text.
    #[props(default)]
    pub aria_label: Option<String>,
    /// Native input/global attributes and events.
    #[props(extends = GlobalAttributes)]
    pub attributes: Vec<Attribute>,
}

/// A checkbox input with the default adico/shadcn visual language.
#[component]
pub fn Checkbox(props: CheckboxProps) -> Element {
    let class = cn(&[
        "peer size-4 shrink-0 rounded-[4px] border border-input shadow-xs outline-none transition-shadow \
         focus-visible:border-ring focus-visible:ring-2 focus-visible:ring-ring/50 \
         disabled:cursor-not-allowed disabled:opacity-50 \
         aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 \
         data-[state=checked]:border-primary data-[state=checked]:bg-primary data-[state=checked]:text-primary-foreground \
         data-[state=indeterminate]:border-primary data-[state=indeterminate]:bg-primary data-[state=indeterminate]:text-primary-foreground",
        props.class.as_deref().unwrap_or_default(),
    ]);
    rsx! {
        CheckboxPrimitive {
            checked: props.checked,
            default_checked: props.default_checked,
            disabled: props.disabled,
            required: props.required,
            name: props.name,
            value: props.value,
            on_checked_change: props.on_checked_change,
            class,
            aria_label: props.aria_label,
            attributes: props.attributes,
            CheckboxIndicatorPrimitive { class: "flex items-center justify-center text-current",
                Check { class: "size-3.5" }
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn checked_state_uses_semantic_primary_surface() {
        let class = cn(&[
            "peer size-4 shrink-0 rounded-[4px] border border-input shadow-xs outline-none transition-shadow \
             focus-visible:border-ring focus-visible:ring-2 focus-visible:ring-ring/50 \
             disabled:cursor-not-allowed disabled:opacity-50 \
             data-[state=checked]:border-primary data-[state=checked]:bg-primary data-[state=checked]:text-primary-foreground \
             data-[state=indeterminate]:border-primary data-[state=indeterminate]:bg-primary data-[state=indeterminate]:text-primary-foreground",
            "",
        ]);
        assert!(class.contains("data-[state=checked]:bg-primary"));
        assert!(class.contains("data-[state=indeterminate]:bg-primary"));
    }
}

//! Small source-owned class composition helper for registry components.

/// Joins non-empty class fragments with one space, preserving caller order.
pub fn cn(classes: &[&str]) -> String {
    classes
        .iter()
        .filter_map(|class| (!class.trim().is_empty()).then_some(class.trim()))
        .collect::<Vec<_>>()
        .join(" ")
}

//! Source-owned shadcn-style Collapsible for Dioxus, backed by the owned
//! adico primitive layer.

use dioxus::prelude::*;

pub use adico_primitives::collapsible::Collapsible;
use adico_primitives::collapsible::{
    CollapsibleContent as PrimitiveCollapsibleContent,
    CollapsibleTrigger as PrimitiveCollapsibleTrigger,
};
use adico_primitives::icons::ChevronDown;

use crate::adico_lib::cn::cn;

/// A trigger button with a chevron affordance that flips based on the
/// primitive's own `data-open` attribute.
#[component]
pub fn CollapsibleTrigger(
    children: Element,
    class: Option<String>,
    #[props(extends = GlobalAttributes)] attributes: Vec<Attribute>,
) -> Element {
    let class = cn(&[
        "flex w-full items-center justify-between gap-4 rounded-md border border-input bg-background px-3 py-2 text-sm font-medium shadow-sm transition-colors hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50 [&[data-open=true]>svg]:rotate-180",
        class.as_deref().unwrap_or_default(),
    ]);
    rsx! {
        PrimitiveCollapsibleTrigger { class, attributes,
            {children}
            ChevronDown { class: "size-4 shrink-0 text-muted-foreground transition-transform duration-200" }
        }
    }
}

/// The collapsible panel, indented and top-padded to read as nested content
/// beneath its trigger.
#[component]
pub fn CollapsibleContent(
    children: Element,
    class: Option<String>,
    #[props(extends = GlobalAttributes)] attributes: Vec<Attribute>,
) -> Element {
    let class = cn(&[
        "mt-2 space-y-2 text-sm",
        class.as_deref().unwrap_or_default(),
    ]);
    rsx! {
        PrimitiveCollapsibleContent { id: ReadSignal::default(), class, attributes, {children} }
    }
}

documentation.usage:
Collapsible { open: open(), on_open_change: move |v| open.set(v),
    CollapsibleTrigger { "Toggle" }
    CollapsibleContent { "Content" }
}

