//! Source-owned shadcn-style Input for Dioxus.

use adico_primitives::icons::{Eye, EyeOff};
use dioxus::prelude::*;

use crate::adico_lib::cn::cn;
use crate::adico_lib::variants::Radius;

/// Props for [`Input`].
#[derive(Props, Clone, PartialEq)]
pub struct InputProps {
    /// Native input type. `"password"` renders a built-in reveal toggle
    /// alongside the field; every other value renders exactly as before.
    #[props(default = "text".to_string())]
    pub r#type: String,
    /// Controlled text value.
    #[props(default)]
    pub value: Option<String>,
    /// Hint shown when the value is empty.
    #[props(default)]
    pub placeholder: Option<String>,
    /// Disables interaction and exposes native disabled semantics.
    #[props(default)]
    pub disabled: Option<bool>,
    /// Prevents edits while allowing focus and selection.
    #[props(default)]
    pub readonly: Option<bool>,
    /// Marks this field as required for native form validation.
    #[props(default)]
    pub required: Option<bool>,
    /// Applies the semantic invalid presentation alongside native `aria-invalid`.
    #[props(default)]
    pub invalid: bool,
    /// Input event handler.
    #[props(default)]
    pub oninput: EventHandler<FormEvent>,
    /// Corner radius of the input surface.
    #[props(default = Radius::Md)]
    pub radius: Radius,
    /// Extra classes appended to the semantic default.
    #[props(default)]
    pub class: Option<String>,
    /// Native input/global attributes and events.
    #[props(extends = GlobalAttributes)]
    #[props(extends = input)]
    pub attributes: Vec<Attribute>,
}

/// A styled single-line text input with the default adico/shadcn visual
/// language. When `r#type` is `"password"`, renders a built-in eye/eye-off
/// reveal toggle rather than requiring the consumer to hand-compose one from
/// `InputGroup` -- the value and `oninput` callback behave identically
/// either way; the toggle only ever changes the field's rendered `type`
/// between `"password"` and `"text"`, never the value itself.
#[component]
pub fn Input(props: InputProps) -> Element {
    let is_password = props.r#type == "password";
    let mut reveal = use_signal(|| false);
    let effective_type = if is_password && reveal() {
        "text".to_string()
    } else {
        props.r#type.clone()
    };

    let class = cn(&[
        "flex h-9 w-full border border-input bg-transparent px-3 py-1 text-sm shadow-sm transition-colors placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-50 read-only:cursor-default read-only:bg-muted aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40",
        props.radius.class(),
        if is_password { "pr-9!" } else { "" },
        props.class.as_deref().unwrap_or_default(),
    ]);

    let field = rsx! {
        input {
            class,
            r#type: effective_type,
            value: props.value,
            placeholder: props.placeholder,
            disabled: props.disabled,
            readonly: props.readonly,
            required: props.required,
            aria_invalid: props.invalid,
            oninput: move |event| props.oninput.call(event),
            ..props.attributes,
        }
    };

    if is_password {
        rsx! {
            div { class: "relative",
                {field}
                button {
                    r#type: "button",
                    class: "absolute inset-y-0 right-0 flex items-center px-2.5 text-muted-foreground hover:text-foreground focus-visible:outline-none",
                    onclick: move |_| reveal.toggle(),
                    if reveal() {
                        EyeOff { class: "size-4" }
                    } else {
                        Eye { class: "size-4" }
                    }
                    span { class: "sr-only", if reveal() { "Hide password" } else { "Show password" } }
                }
            }
        }
    } else {
        field
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn password_reveal_reserves_space_without_relying_on_class_order() {
        // `cn` is a plain space-join, not a tailwind-merge conflict
        // resolver -- `pr-9!` (an important override) is required here so
        // it deterministically wins over the base class's `px-3`,
        // regardless of Tailwind's compiled utility order.
        let class = cn(&["px-3", "pr-9!", ""]);
        assert!(class.contains("pr-9!"));
    }
}

//! Source-owned shadcn-style InputGroup for Dioxus.
//!
//! `InputGroupAddon` omits upstream's click-to-focus-the-adjoining-input
//! JavaScript behavior (a UX nicety, not required for the addon to function):
//! this repository's `document`-eval-based DOM interop has repeatedly been
//! found unreliable in this sandbox (see `docs/adico/m4-acceptance.md`'s
//! "the other symptom-class of `document`-eval defects"), so this batch does
//! not add a new instance of it for a non-essential effect. `InputGroupInput`
//! and `InputGroupTextarea` author their own flush (borderless, transparent)
//! classes rather than composing `Input`/`Textarea` and overriding their
//! fixed classes: `adico_lib::cn::cn` is plain string concatenation with no
//! Tailwind-merge equivalent, so two conflicting single-class selectors
//! (e.g. `border-input` vs. an appended `border-0`) have no reliable winner --
//! generated CSS cascade order, not class-attribute order, decides. Authoring
//! the flush classes directly avoids depending on an ordering guarantee this
//! toolchain doesn't provide.

use dioxus::prelude::*;

use super::button::{Button, ButtonSize, ButtonVariant};
use crate::adico_lib::cn::cn;
use crate::adico_lib::variants::Radius;

/// Where an [`InputGroupAddon`] sits relative to its sibling control.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum InputGroupAlign {
    /// Leading edge, inline with a single-line control.
    #[default]
    InlineStart,
    /// Trailing edge, inline with a single-line control.
    InlineEnd,
    /// Leading edge, stacked above a multi-line control.
    BlockStart,
    /// Trailing edge, stacked below a multi-line control.
    BlockEnd,
}

impl InputGroupAlign {
    fn attr(self) -> &'static str {
        match self {
            Self::InlineStart => "inline-start",
            Self::InlineEnd => "inline-end",
            Self::BlockStart => "block-start",
            Self::BlockEnd => "block-end",
        }
    }

    fn class(self) -> &'static str {
        match self {
            Self::InlineStart => "order-first pl-3",
            Self::InlineEnd => "order-last pr-3",
            Self::BlockStart => {
                "order-first w-full justify-start px-3 pt-3 group-has-[>input]/input-group:pt-2.5"
            }
            Self::BlockEnd => {
                "order-last w-full justify-start px-3 pb-3 group-has-[>input]/input-group:pb-2.5"
            }
        }
    }
}

/// The bordered container joining an input/textarea control with its
/// [`InputGroupAddon`]s into one visual field.
#[component]
pub fn InputGroup(
    #[props(default = Radius::Md)] radius: Radius,
    class: Option<String>,
    children: Element,
) -> Element {
    let class = cn(&[
        "group/input-group relative flex w-full items-center border border-input shadow-xs outline-none transition-[color,box-shadow]",
        "h-9 min-w-0 has-[>textarea]:h-auto",
        "has-[>[data-align=block-start]]:h-auto has-[>[data-align=block-start]]:flex-col has-[>[data-align=block-end]]:h-auto has-[>[data-align=block-end]]:flex-col",
        "has-[[data-slot=input-group-control]:focus-visible]:border-ring has-[[data-slot=input-group-control]:focus-visible]:ring-[3px] has-[[data-slot=input-group-control]:focus-visible]:ring-ring/50",
        "has-[[data-slot][aria-invalid=true]]:border-destructive has-[[data-slot][aria-invalid=true]]:ring-destructive/20 dark:has-[[data-slot][aria-invalid=true]]:ring-destructive/40",
        radius.class(),
        class.as_deref().unwrap_or_default(),
    ]);
    rsx! {
        div { role: "group", "data-slot": "input-group", class, {children} }
    }
}

/// A leading/trailing decoration (icon, [`InputGroupButton`], [`InputGroupText`])
/// within an [`InputGroup`].
#[component]
pub fn InputGroupAddon(
    #[props(default)] align: InputGroupAlign,
    class: Option<String>,
    children: Element,
) -> Element {
    let class = cn(&[
        "flex h-auto cursor-text items-center justify-center gap-2 py-1.5 text-sm font-medium text-muted-foreground select-none [&>svg:not([class*='size-'])]:size-4",
        align.class(),
        class.as_deref().unwrap_or_default(),
    ]);
    rsx! {
        div {
            role: "group",
            "data-slot": "input-group-addon",
            "data-align": align.attr(),
            class,
            {children}
        }
    }
}

/// A [`Button`] sized to sit inside an [`InputGroupAddon`]. Reuses `Button`'s
/// own [`ButtonVariant`]/[`ButtonSize`] scale directly rather than a
/// duplicate parallel one -- adico's `Xs`/`IconXs`/`Sm`/`IconSm` sizes already
/// match upstream's `xs`/`icon-xs`/`sm`/`icon-sm` addon-button sizes.
#[component]
pub fn InputGroupButton(
    #[props(default = ButtonVariant::Ghost)] variant: ButtonVariant,
    #[props(default = ButtonSize::Xs)] size: ButtonSize,
    class: Option<String>,
    #[props(default)] onclick: EventHandler<MouseEvent>,
    /// Forwarded straight to the inner [`Button`]; see its own `loading` doc
    /// comment.
    #[props(default)]
    loading: bool,
    #[props(default)] loading_text: Option<String>,
    children: Element,
) -> Element {
    let class = cn(&["shadow-none", class.as_deref().unwrap_or_default()]);
    rsx! {
        Button {
            variant,
            size,
            class,
            onclick,
            loading,
            loading_text,
            {children}
        }
    }
}

/// Non-interactive text within an [`InputGroup`] (e.g. a fixed unit or prefix).
#[component]
pub fn InputGroupText(class: Option<String>, children: Element) -> Element {
    let class = cn(&[
        "flex items-center gap-2 text-sm text-muted-foreground [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4",
        class.as_deref().unwrap_or_default(),
    ]);
    rsx! {
        span { class, {children} }
    }
}

/// A borderless, transparent single-line control for an [`InputGroup`]. See
/// this module's doc comment for why it authors its own classes rather than
/// composing [`super::input::Input`]. Deliberately has no `radius` prop of
/// its own: its `rounded-none` is required to stay flush with the group's
/// own border (`InputGroup` owns the visible corner); an independent radius
/// here would visually break that flush-field look.
#[component]
pub fn InputGroupInput(
    #[props(default = "text".to_string())] r#type: String,
    #[props(default)] value: Option<String>,
    #[props(default)] placeholder: Option<String>,
    #[props(default)] disabled: Option<bool>,
    #[props(default)] invalid: bool,
    #[props(default)] oninput: EventHandler<FormEvent>,
    class: Option<String>,
    #[props(extends = GlobalAttributes)]
    #[props(extends = input)]
    attributes: Vec<Attribute>,
) -> Element {
    let class = cn(&[
        "flex-1 rounded-none border-0 bg-transparent px-3 py-1 text-sm shadow-none outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed disabled:opacity-50",
        class.as_deref().unwrap_or_default(),
    ]);
    rsx! {
        input {
            "data-slot": "input-group-control",
            class,
            r#type,
            value,
            placeholder,
            disabled,
            aria_invalid: invalid,
            oninput: move |event| oninput.call(event),
            ..attributes,
        }
    }
}

/// A borderless, transparent multi-line control for an [`InputGroup`]. See
/// this module's doc comment for why it authors its own classes rather than
/// composing [`super::textarea::Textarea`]. Deliberately has no `radius`
/// prop of its own — see [`InputGroupInput`]'s own doc comment for why.
#[component]
pub fn InputGroupTextarea(
    #[props(default)] value: Option<String>,
    #[props(default)] placeholder: Option<String>,
    #[props(default)] disabled: Option<bool>,
    #[props(default)] invalid: bool,
    #[props(default)] rows: Option<u32>,
    #[props(default)] oninput: EventHandler<FormEvent>,
    class: Option<String>,
    #[props(extends = GlobalAttributes)]
    #[props(extends = textarea)]
    attributes: Vec<Attribute>,
) -> Element {
    let class = cn(&[
        "w-full flex-1 resize-none rounded-none border-0 bg-transparent px-3 py-3 text-sm shadow-none outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed disabled:opacity-50",
        class.as_deref().unwrap_or_default(),
    ]);
    rsx! {
        textarea {
            "data-slot": "input-group-control",
            class,
            value,
            placeholder,
            disabled,
            rows,
            aria_invalid: invalid,
            oninput: move |event| oninput.call(event),
            ..attributes,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn addon_alignments_target_the_correct_edge() {
        assert!(InputGroupAlign::InlineStart.class().contains("order-first"));
        assert!(InputGroupAlign::InlineEnd.class().contains("order-last"));
        assert_eq!(InputGroupAlign::BlockStart.attr(), "block-start");
        assert_eq!(InputGroupAlign::BlockEnd.attr(), "block-end");
    }

    #[test]
    fn controls_remain_visually_flush_with_the_group_border() {
        let class = cn(&["rounded-none border-0 bg-transparent shadow-none"]);
        assert!(class.contains("border-0"));
    }
}

documentation.usage:
InputGroup {
    InputGroupAddon { InputGroupText { "$" } }
    InputGroupInput { placeholder: "0.00" }
}

