//! Source-owned shadcn-style Item composition for Dioxus.

use dioxus::prelude::*;

use crate::adico_lib::cn::cn;
use crate::adico_lib::variants::Radius;

/// A vertical list of [`Item`] rows.
#[derive(Props, Clone, PartialEq)]
pub struct ItemGroupProps {
    #[props(default)]
    pub class: Option<String>,
    #[props(extends = GlobalAttributes)]
    #[props(extends = div)]
    pub attributes: Vec<Attribute>,
    pub children: Element,
}

#[component]
pub fn ItemGroup(props: ItemGroupProps) -> Element {
    let class = cn(&["flex flex-col", props.class.as_deref().unwrap_or_default()]);
    rsx! {
        div { class, role: "list", ..props.attributes, {props.children} }
    }
}

/// Visual and interaction treatment for an [`Item`] row.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum ItemVariant {
    /// A bordered row suitable for independently actionable content.
    #[default]
    Default,
    /// A quiet row with no outer border.
    Muted,
    /// A bordered row with no background fill, matching upstream shadcn's
    /// `outline` item variant (missing here until this audit found the gap).
    Outline,
    /// A row that advertises pointer and keyboard focus affordances.
    Interactive,
}

impl ItemVariant {
    fn class(self) -> &'static str {
        match self {
            Self::Default => "border bg-card",
            Self::Muted => "border-transparent bg-muted/50",
            Self::Outline => "border border-border",
            Self::Interactive => {
                "border bg-card cursor-pointer hover:bg-accent hover:text-accent-foreground"
            }
        }
    }
}

/// The overall size of an [`Item`] row, matching shadcn's own
/// `"default" | "sm"` cva axis.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum ItemSize {
    Sm,
    #[default]
    Default,
}

impl ItemSize {
    fn class(self) -> &'static str {
        match self {
            Self::Sm => "gap-3 p-3",
            Self::Default => "gap-4 p-4",
        }
    }
}

/// A single row combining optional media, content, and actions.
#[derive(Props, Clone, PartialEq)]
pub struct ItemProps {
    #[props(default)]
    pub variant: ItemVariant,
    /// Overall row size; see [`ItemSize`].
    #[props(default)]
    pub size: ItemSize,
    /// `Item` renders a `div`, which has no native HTML `disabled` attribute
    /// to defer to (unlike `Button`/`Input`'s categories) — disabling here
    /// is entirely synthetic (`aria-disabled`, a manual `onclick` guard, and
    /// the `Interactive` variant's tabindex), so this intentionally stays a
    /// plain `bool` rather than the `Option<bool>`/`ReadSignal<bool>`
    /// convention that applies to components with a real disabled state to
    /// mirror.
    #[props(default)]
    pub disabled: bool,
    #[props(default)]
    pub onclick: EventHandler<MouseEvent>,
    /// Corner radius of the row surface.
    #[props(default = Radius::Md)]
    pub radius: Radius,
    #[props(default)]
    pub class: Option<String>,
    #[props(extends = GlobalAttributes)]
    #[props(extends = div)]
    pub attributes: Vec<Attribute>,
    pub children: Element,
}

#[component]
pub fn Item(props: ItemProps) -> Element {
    let class = cn(&[
        "flex items-center text-sm outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
        props.variant.class(),
        props.size.class(),
        props.radius.class(),
        if props.disabled {
            "pointer-events-none opacity-50"
        } else {
            ""
        },
        props.class.as_deref().unwrap_or_default(),
    ]);
    rsx! {
        div {
            class,
            role: "listitem",
            tabindex: if props.variant == ItemVariant::Interactive && !props.disabled { 0 } else { -1 },
            "aria-disabled": props.disabled,
            onclick: move |event| if !props.disabled { props.onclick.call(event) },
            ..props.attributes,
            {props.children}
        }
    }
}

/// The content shape of an [`ItemMedia`] slot, matching shadcn's own
/// `"default" | "icon" | "image"` cva axis.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum ItemMediaVariant {
    /// No fixed sizing or background of its own, the existing default look.
    #[default]
    Default,
    /// A small icon tile with a muted background.
    Icon,
    /// A larger image thumbnail with no background chrome of its own.
    Image,
}

impl ItemMediaVariant {
    fn class(self) -> &'static str {
        match self {
            Self::Default => "",
            Self::Icon => "size-8 rounded-md bg-muted text-muted-foreground",
            Self::Image => {
                "size-10 overflow-hidden rounded-md [&>img]:size-full [&>img]:object-cover"
            }
        }
    }
}

/// A leading icon, avatar, or image slot for an [`Item`].
#[derive(Props, Clone, PartialEq)]
pub struct ItemMediaProps {
    /// Content shape; see [`ItemMediaVariant`].
    #[props(default)]
    pub variant: ItemMediaVariant,
    #[props(default)]
    pub class: Option<String>,
    #[props(extends = GlobalAttributes)]
    #[props(extends = div)]
    pub attributes: Vec<Attribute>,
    pub children: Element,
}

#[component]
pub fn ItemMedia(props: ItemMediaProps) -> Element {
    let class = cn(&[
        "flex shrink-0 items-center justify-center",
        props.variant.class(),
        props.class.as_deref().unwrap_or_default(),
    ]);
    rsx! {
        div { class, ..props.attributes, {props.children} }
    }
}

/// The flexible text region of an [`Item`], holding title/description.
#[derive(Props, Clone, PartialEq)]
pub struct ItemContentProps {
    #[props(default)]
    pub class: Option<String>,
    #[props(extends = GlobalAttributes)]
    #[props(extends = div)]
    pub attributes: Vec<Attribute>,
    pub children: Element,
}

#[component]
pub fn ItemContent(props: ItemContentProps) -> Element {
    let class = cn(&[
        "flex flex-1 flex-col gap-1",
        props.class.as_deref().unwrap_or_default(),
    ]);
    rsx! {
        div { class, ..props.attributes, {props.children} }
    }
}

/// The primary label of an [`Item`].
#[derive(Props, Clone, PartialEq)]
pub struct ItemTitleProps {
    #[props(default)]
    pub class: Option<String>,
    #[props(extends = GlobalAttributes)]
    #[props(extends = div)]
    pub attributes: Vec<Attribute>,
    pub children: Element,
}

#[component]
pub fn ItemTitle(props: ItemTitleProps) -> Element {
    let class = cn(&[
        "text-sm font-medium leading-none",
        props.class.as_deref().unwrap_or_default(),
    ]);
    rsx! {
        div { class, ..props.attributes, {props.children} }
    }
}

/// Supporting text placed under an [`ItemTitle`].
#[derive(Props, Clone, PartialEq)]
pub struct ItemDescriptionProps {
    #[props(default)]
    pub class: Option<String>,
    #[props(extends = GlobalAttributes)]
    #[props(extends = div)]
    pub attributes: Vec<Attribute>,
    pub children: Element,
}

#[component]
pub fn ItemDescription(props: ItemDescriptionProps) -> Element {
    let class = cn(&[
        "text-sm text-muted-foreground",
        props.class.as_deref().unwrap_or_default(),
    ]);
    rsx! {
        div { class, ..props.attributes, {props.children} }
    }
}

/// A trailing slot for buttons or other controls on an [`Item`].
#[derive(Props, Clone, PartialEq)]
pub struct ItemActionsProps {
    #[props(default)]
    pub class: Option<String>,
    #[props(extends = GlobalAttributes)]
    #[props(extends = div)]
    pub attributes: Vec<Attribute>,
    pub children: Element,
}

#[component]
pub fn ItemActions(props: ItemActionsProps) -> Element {
    let class = cn(&[
        "flex items-center gap-2",
        props.class.as_deref().unwrap_or_default(),
    ]);
    rsx! {
        div { class, ..props.attributes, {props.children} }
    }
}

/// A full-width row above an [`Item`]'s main content, e.g. for grouped headers.
#[derive(Props, Clone, PartialEq)]
pub struct ItemHeaderProps {
    #[props(default)]
    pub class: Option<String>,
    #[props(extends = GlobalAttributes)]
    #[props(extends = div)]
    pub attributes: Vec<Attribute>,
    pub children: Element,
}

#[component]
pub fn ItemHeader(props: ItemHeaderProps) -> Element {
    let class = cn(&[
        "flex basis-full items-center justify-between gap-2",
        props.class.as_deref().unwrap_or_default(),
    ]);
    rsx! {
        div { class, ..props.attributes, {props.children} }
    }
}

/// A full-width row below an [`Item`]'s main content.
#[derive(Props, Clone, PartialEq)]
pub struct ItemFooterProps {
    #[props(default)]
    pub class: Option<String>,
    #[props(extends = GlobalAttributes)]
    #[props(extends = div)]
    pub attributes: Vec<Attribute>,
    pub children: Element,
}

#[component]
pub fn ItemFooter(props: ItemFooterProps) -> Element {
    let class = cn(&[
        "flex basis-full items-center justify-between gap-2",
        props.class.as_deref().unwrap_or_default(),
    ]);
    rsx! {
        div { class, ..props.attributes, {props.children} }
    }
}

/// A thin horizontal rule between items in an [`ItemGroup`].
#[derive(Props, Clone, PartialEq)]
pub struct ItemSeparatorProps {
