//! Source-owned shadcn-style Switch for Dioxus, backed by the owned adico
//! primitive layer.

use dioxus::prelude::*;

use adico_primitives::switch::{Switch as SwitchPrimitive, SwitchThumb as SwitchThumbPrimitive};

use crate::adico_lib::cn::cn;
use crate::adico_lib::variants::Radius;

/// The visual size of a [`Switch`]. Was entirely absent before task 5.2 --
/// upstream shadcn added a `size` axis (`sm`/`default`) to this component;
/// adico had only ever rendered the `default` size, a real, missing
/// capability rather than a styling nuance.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum SwitchSize {
    /// Compact size.
    Sm,
    /// Default size.
    #[default]
    Default,
}

impl SwitchSize {
    fn track_class(self) -> &'static str {
        match self {
            Self::Sm => "h-3.5 w-6",
            Self::Default => "h-[1.15rem] w-8",
        }
    }

    fn thumb_class(self) -> &'static str {
        match self {
            Self::Sm => "size-3",
            Self::Default => "size-4",
        }
    }
}

/// Props for [`Switch`].
#[derive(Props, Clone, PartialEq)]
pub struct SwitchProps {
    /// The controlled checked state of the switch.
    #[props(default)]
    pub checked: ReadSignal<Option<bool>>,
    /// The default checked state when uncontrolled.
    #[props(default = false)]
    pub default_checked: bool,
    /// Whether the switch is disabled.
    #[props(default)]
    pub disabled: ReadSignal<bool>,
    /// Whether the switch is required in a form.
    #[props(default)]
    pub required: ReadSignal<bool>,
    /// The name attribute for form submission.
    #[props(default)]
    pub name: ReadSignal<String>,
    /// The value attribute for form submission.
    #[props(default = ReadSignal::new(Signal::new(String::from("on"))))]
    pub value: ReadSignal<String>,
    /// The visual size.
    #[props(default)]
    pub size: SwitchSize,
    /// Corner radius of the track and thumb (kept in sync between the two).
    #[props(default = Radius::Full)]
    pub radius: Radius,
    /// Callback fired when the checked state changes.
    #[props(default)]
    pub on_checked_change: Callback<bool>,
    /// Extra classes appended to the semantic default.
    #[props(default)]
    pub class: Option<String>,
    /// Accessible label, since the switch itself has no visible text.
    #[props(default)]
    pub aria_label: Option<String>,
    /// Native input/global attributes and events.
    #[props(extends = GlobalAttributes)]
    pub attributes: Vec<Attribute>,
}

/// A toggle switch with the default adico/shadcn visual language.
#[component]
pub fn Switch(props: SwitchProps) -> Element {
    let class = cn(&[
        "peer group inline-flex shrink-0 items-center border border-transparent shadow-xs outline-none transition-colors \
         focus-visible:ring-2 focus-visible:ring-ring/50 \
         disabled:cursor-not-allowed disabled:opacity-50 \
         data-[state=checked]:bg-primary data-[state=unchecked]:bg-input",
        props.size.track_class(),
        props.radius.class(),
        props.class.as_deref().unwrap_or_default(),
    ]);
    // `group-data-[state=...]`, not a plain `data-[state=...]`: `data-state`
    // lives on the track (`Switch`, above), not on this thumb `span` itself
    // -- a bare `data-[state=checked]:translate-x-...` here matches this
    // element's own (nonexistent) attribute, so the thumb never translates
    // regardless of checked state (found live: the track colors correctly
    // but the thumb sits frozen at the unchecked position).
    let thumb_class = cn(&[
        "pointer-events-none block bg-background shadow-lg ring-0 transition-transform \
         group-data-[state=checked]:translate-x-[calc(100%-2px)] group-data-[state=unchecked]:translate-x-0",
        props.size.thumb_class(),
        props.radius.class(),
    ]);
    rsx! {
        SwitchPrimitive {
            checked: props.checked,
            default_checked: props.default_checked,
            disabled: props.disabled,
            required: props.required,
            name: props.name,
            value: props.value,
            on_checked_change: props.on_checked_change,
            class,
            aria_label: props.aria_label,
            attributes: props.attributes,
            SwitchThumbPrimitive { class: thumb_class }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn track_class_switches_semantic_surface_by_state() {
        let class = cn(&[
            "peer inline-flex h-[1.15rem] w-8 shrink-0 items-center rounded-full border border-transparent shadow-xs outline-none transition-colors \
             focus-visible:ring-2 focus-visible:ring-ring/50 \
             disabled:cursor-not-allowed disabled:opacity-50 \
             data-[state=checked]:bg-primary data-[state=unchecked]:bg-input",
            "",
        ]);
        assert!(class.contains("data-[state=checked]:bg-primary"));
        assert!(class.contains("data-[state=unchecked]:bg-input"));
    }

    #[test]
    fn thumb_translates_off_the_track_s_own_state_not_its_own() {
        let class = cn(&[
            "group-data-[state=checked]:translate-x-[calc(100%-2px)] group-data-[state=unchecked]:translate-x-0",
            "",
        ]);
        assert!(class.contains("group-data-[state=checked]:translate-x"));
        assert!(!class.contains(" data-[state=checked]:translate-x"));
    }
}

//! Source-owned shadcn-style Table for Dioxus.

use dioxus::prelude::*;

use adico_primitives::scroll_area::scroll_area_visibility_class;

use crate::adico_lib::cn::cn;

/// The scroll-container-wrapped `<table>` root.
#[component]
pub fn Table(class: Option<String>, children: Element) -> Element {
    let class = cn(&[
        "w-full caption-bottom text-sm",
        class.as_deref().unwrap_or_default(),
    ]);
    let wrapper_class = cn(&[
        "relative w-full overflow-x-auto",
        scroll_area_visibility_class(false),
    ]);
    rsx! {
        div { class: wrapper_class,
            table { class, {children} }
        }
    }
}

/// The `<thead>` region.
#[component]
pub fn TableHeader(class: Option<String>, children: Element) -> Element {
    let class = cn(&["[&_tr]:border-b", class.as_deref().unwrap_or_default()]);
    rsx! {
        thead { class, {children} }
    }
}

/// The `<tbody>` region.
#[component]
pub fn TableBody(class: Option<String>, children: Element) -> Element {
    let class = cn(&[
        "[&_tr:last-child]:border-0",
        class.as_deref().unwrap_or_default(),
    ]);
    rsx! {
        tbody { class, {children} }
    }
}

/// The `<tfoot>` region.
#[component]
pub fn TableFooter(class: Option<String>, children: Element) -> Element {
    let class = cn(&[
        "border-t bg-muted/50 font-medium [&>tr]:last:border-b-0",
        class.as_deref().unwrap_or_default(),
    ]);
    rsx! {
        tfoot { class, {children} }
    }
}

/// Props for [`TableRow`].
#[derive(Props, Clone, PartialEq)]
pub struct TableRowProps {
    /// Extra semantic classes appended to the default treatment.
    #[props(default)]
    pub class: Option<String>,
    /// Native `<tr>` and global attributes. In particular, set `"data-state":
    /// "selected"` here to trigger this row's own `data-[state=selected]:bg-muted`
    /// styling -- that class had no way to ever fire before this prop existed,
    /// since a bare function-argument component (this one's original shape)
    /// cannot accept arbitrary attributes the way every other styled
    /// component in this registry does.
    #[props(extends = GlobalAttributes)]
    #[props(extends = tr)]
    pub attributes: Vec<Attribute>,
    /// The row's cells.
    pub children: Element,
}

/// A `<tr>` row.
#[component]
pub fn TableRow(props: TableRowProps) -> Element {
    let class = cn(&[
        "border-b transition-colors hover:bg-muted/50 has-aria-expanded:bg-muted/50 data-[state=selected]:bg-muted",
        props.class.as_deref().unwrap_or_default(),
    ]);
    rsx! {
        tr { class, ..props.attributes, {props.children} }
    }
}

/// A `<th>` header cell.
#[component]
pub fn TableHead(class: Option<String>, children: Element) -> Element {
    let class = cn(&[
        "h-10 px-2 text-left align-middle font-medium whitespace-nowrap text-foreground [&:has([role=checkbox])]:pr-0 [&>[role=checkbox]]:translate-y-[2px]",
        class.as_deref().unwrap_or_default(),
    ]);
    rsx! {
        th { class, {children} }
    }
}

/// A `<td>` body cell.
#[component]
pub fn TableCell(class: Option<String>, children: Element) -> Element {
    let class = cn(&[
        "p-2 align-middle whitespace-nowrap [&:has([role=checkbox])]:pr-0 [&>[role=checkbox]]:translate-y-[2px]",
        class.as_deref().unwrap_or_default(),
    ]);
    rsx! {
        td { class, {children} }
    }
}

/// A `<caption>`.
#[component]
pub fn TableCaption(class: Option<String>, children: Element) -> Element {
    let class = cn(&[
        "mt-4 text-sm text-muted-foreground",
        class.as_deref().unwrap_or_default(),
    ]);
    rsx! {
        caption { class, {children} }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn header_and_footer_use_semantic_surfaces() {
        let footer_class = cn(&["border-t bg-muted/50 font-medium [&>tr]:last:border-b-0"]);
        assert!(footer_class.contains("bg-muted/50"));
        let head_class =
            cn(&["h-10 px-2 text-left align-middle font-medium whitespace-nowrap text-foreground"]);
        assert!(head_class.contains("text-foreground"));
    }
}

documentation.usage:
Table {
    TableHeader { TableRow { TableHead { "Name" } } }
    TableBody { TableRow { TableCell { "adico" } } }
}

