            "Appearance"
            select {
                class: "rounded-md border border-input bg-background px-2 py-1.5 text-sm text-foreground",
                value: "{value.value()}",
                onchange: move |event| {
                    if let Some(appearance) = ThemeAppearance::from_value(&event.value()) {
                        on_change.call(appearance);
                    }
