#[component]
fn SemanticTokenControl(
    token: ThemeToken,
    value: String,
    on_change: EventHandler<String>,
) -> Element {
    let label = token.label();
    if token.is_color() {
        let color_value = hsl_to_hex(&value).unwrap_or_else(|| "#000000".to_string());
        rsx! {
            label { class: "grid gap-1 text-xs",
                code { class: "text-[10px] text-muted-foreground", "{label}" }
                div { class: "flex items-center gap-2",
                    input {
                        class: "h-8 w-10 cursor-pointer rounded border border-input bg-background p-0.5",
                        r#type: "color",
                        value: "{color_value}",
                        onchange: move |event| {
                            if let Some(hsl) = hex_to_hsl(&event.value()) {
                                on_change.call(hsl);
                            }
                        },
                    }
                    code { class: "min-w-0 truncate text-[10px] text-muted-foreground", "{value}" }
                }
            }
        }
    } else {
        rsx! {
            label { class: "grid gap-1 text-xs",
                code { class: "text-[10px] text-muted-foreground", "{label}" }
                input {
                    class: "rounded-md border border-input bg-background px-2 py-1 text-xs text-foreground",
                    r#type: "text",
                    value: "{value}",
                    oninput: move |event| on_change.call(event.value()),
                }
            }
        }
    }
}

fn hsl_to_hex(value: &str) -> Option<String> {
    let (hue, saturation, lightness) = parse_hsl(value)?;
    let chroma = (1.0 - (2.0 * lightness - 1.0).abs()) * saturation;
    let hue_sector = hue / 60.0;
    let x = chroma * (1.0 - (hue_sector.rem_euclid(2.0) - 1.0).abs());
    let (red, green, blue) = match hue_sector {
        value if value < 1.0 => (chroma, x, 0.0),
        value if value < 2.0 => (x, chroma, 0.0),
        value if value < 3.0 => (0.0, chroma, x),
        value if value < 4.0 => (0.0, x, chroma),
        value if value < 5.0 => (x, 0.0, chroma),
        _ => (chroma, 0.0, x),
    };
    let offset = lightness - chroma / 2.0;
    Some(format!(
        "#{:02x}{:02x}{:02x}",
        ((red + offset) * 255.0).round() as u8,
        ((green + offset) * 255.0).round() as u8,
        ((blue + offset) * 255.0).round() as u8,
    ))
}

fn hex_to_hsl(value: &str) -> Option<String> {
    let hex = value.strip_prefix('#')?;
    if hex.len() != 6 {
        return None;
    }
    let red = u8::from_str_radix(&hex[0..2], 16).ok()? as f64 / 255.0;
    let green = u8::from_str_radix(&hex[2..4], 16).ok()? as f64 / 255.0;
    let blue = u8::from_str_radix(&hex[4..6], 16).ok()? as f64 / 255.0;
    let max = red.max(green).max(blue);
    let min = red.min(green).min(blue);
    let difference = max - min;
    let lightness = (max + min) / 2.0;
    let saturation = if difference == 0.0 {
        0.0
    } else {
        difference / (1.0 - (2.0 * lightness - 1.0).abs())
    };
    let hue = if difference == 0.0 {
        0.0
    } else if max == red {
        60.0 * ((green - blue) / difference).rem_euclid(6.0)
    } else if max == green {
        60.0 * ((blue - red) / difference + 2.0)
    } else {
        60.0 * ((red - green) / difference + 4.0)
    };
    Some(format!(
        "{hue:.1} {:.1}% {:.1}%",
        saturation * 100.0,
        lightness * 100.0
    ))
}

fn parse_hsl(value: &str) -> Option<(f64, f64, f64)> {
    let mut values = value.split_ascii_whitespace();
    let hue = values.next()?.parse::<f64>().ok()?.rem_euclid(360.0);
    let saturation = values.next()?.strip_suffix('%')?.parse::<f64>().ok()? / 100.0;
    let lightness = values.next()?.strip_suffix('%')?.parse::<f64>().ok()? / 100.0;
    if values.next().is_some()
        || !(0.0..=1.0).contains(&saturation)
        || !(0.0..=1.0).contains(&lightness)
    {
        return None;
    }
    Some((hue, saturation, lightness))
}

#[cfg(test)]
mod tests {
    use super::{
        Palette, ThemeAppearance, ThemeSelection, ThemeToken, ThemeVariables, hex_to_hsl,
        hsl_to_hex, hydrate_tokens,
    };

    #[test]
    fn palette_matching_round_trips_every_preset_and_appearance() {
        for appearance in ThemeAppearance::ALL {
            for palette in Palette::ALL {
                let primary = palette.primary_tokens(appearance);
                assert_eq!(
                    Palette::matching_primary(primary.background, primary.foreground, appearance),
                    Some(palette)
                );
                let surface = palette.surface_tokens(appearance);
                assert_eq!(
                    Palette::matching_surface(surface.background, surface.foreground, appearance),
                    Some(palette)
                );
            }
        }
    }

    #[test]
    fn palette_matching_is_none_for_an_unrecognized_value() {
        assert_eq!(
            Palette::matching_primary("1 2% 3%", "4 5% 6%", ThemeAppearance::Light),
            None
        );
    }

    #[test]
    fn every_palette_combination_supplies_the_complete_semantic_contract() {
        for primary in Palette::ALL {
            for secondary in Palette::ALL {
                for accent in Palette::ALL {
                    let mut selection = ThemeSelection::default();
                    selection.set_primary_palette(primary);
                    selection.set_secondary_palette(secondary);
                    selection.set_accent_palette(accent);
                    for appearance in ThemeAppearance::ALL {
                        selection.appearance = appearance;
                        let pairs = selection.active_tokens().root_property_pairs();
                        for token in [
                            "--background",
                            "--primary",
                            "--secondary",
                            "--accent",
                            "--destructive",
                            "--success",
                            "--warning",
                            "--info",
                            "--border",
                            "--input",
                            "--ring",
                            "--radius",
                            "--sidebar",
                            "--sidebar-primary",
                            "--sidebar-accent",
                        ] {
                            assert!(
                                pairs.iter().any(|(name, _)| *name == token),
                                "missing {token}"
                            );
                        }
                        assert!(
                            pairs.iter().all(|(name, _)| !name.starts_with("--color-")),
                            "root_property_pairs should stick to raw tokens -- the installed \
                             @theme block already derives --color-* aliases from them live"
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn direct_edits_stay_with_the_selected_appearance() {
        let mut selection = ThemeSelection::default();
        selection
            .active_tokens_mut()
            .set(ThemeToken::Background, "240 100% 50%".into());
        selection.appearance = ThemeAppearance::Dark;
        assert_ne!(
            selection.active_tokens().get(ThemeToken::Background),
            "240 100% 50%"
        );
        selection.appearance = ThemeAppearance::Light;
        assert_eq!(
            selection.active_tokens().get(ThemeToken::Background),
            "240 100% 50%"
        );
    }

    #[test]
    fn generated_themes_change_the_palette_selection() {
        let mut selection = ThemeSelection::default();
        let initial = (
            selection.primary_palette,
            selection.secondary_palette,
            selection.accent_palette,
        );
        selection.generate_theme();
        assert_ne!(
            (
                selection.primary_palette,
                selection.secondary_palette,
                selection.accent_palette,
            ),
            initial
        );
    }

    #[test]
    fn color_picker_conversion_round_trips() {
        let hsl = "221.2 83.2% 53.3%";
        let hex = hsl_to_hex(hsl).expect("fixture HSL should convert");
        let round_trip = hex_to_hsl(&hex).expect("generated hex should convert");
        assert_eq!(hsl_to_hex(&round_trip), Some(hex));
    }

    #[test]
    fn token_overrides_update_the_raw_root_property_only() {
        let mut selection = ThemeSelection::default();
        selection
            .active_tokens_mut()
            .set(ThemeToken::Primary, "221.2 83.2% 53.3%".into());
        let pairs = selection.active_tokens().root_property_pairs();
        assert!(
            pairs
                .iter()
                .any(|(name, value)| *name == "--primary" && value == "221.2 83.2% 53.3%")
        );
        assert!(
            !pairs.iter().any(|(name, _)| *name == "--color-primary"),
            "no --color-primary pair should be written -- the installed @theme block's \
             var(--primary) lookup already derives it live from the raw property above"
        );
    }

    #[test]
    fn css_export_uses_the_active_appearance_and_canonical_theme_tokens() {
        let mut selection = ThemeSelection::default();
        selection
            .active_tokens_mut()
            .set(ThemeToken::Primary, "221.2 83.2% 53.3%".into());
        let light_css = selection.css_export();
        assert!(light_css.starts_with(":root {"));
        assert!(light_css.contains("--primary: 221.2 83.2% 53.3%;"));
        assert!(light_css.contains("--sidebar-ring:"));
        assert!(!light_css.contains("--color-primary:"));

        selection.appearance = ThemeAppearance::Dark;
        assert!(selection.css_export().starts_with(".dark {"));
    }

    #[test]
    fn hydrate_tokens_adopts_read_values_and_skips_empty_ones() {
        let mut variables = ThemeVariables::light();
        let tokens = [ThemeToken::Primary, ThemeToken::Background];
        let values = ["1 2% 3%".to_string(), String::new()];
        hydrate_tokens(&mut variables, &tokens, &values);
        assert_eq!(variables.primary, "1 2% 3%");
        assert_eq!(variables.background, ThemeVariables::light().background);
    }

    #[test]
    fn hydrate_tokens_is_a_no_op_on_a_length_mismatch() {
        let mut variables = ThemeVariables::light();
        let before = variables.clone();
        hydrate_tokens(&mut variables, &[ThemeToken::Primary], &[]);
        assert_eq!(variables, before);
    }

    #[test]
    fn reset_restores_the_default_theme() {
        let mut selection = ThemeSelection::default();
        selection.generate_theme();
        selection.appearance = ThemeAppearance::Dark;
        selection.reset();
        assert_eq!(selection, ThemeSelection::default());
    }
}

//! A source-owned Dioxus-only palette switcher (no shadcn equivalent).
//!
//! Productizes the palette preset concept prototyped in
//! `apps/playground/src/theme.rs`'s advanced customization tray, distilled to
//! just the palette-selection experience: **one** [`super::select::Select`]
//! whose options each set the primary, secondary, and accent semantic role
//! groups together as one coordinated preset -- rather than that tray's full
//! 28-token editor (`theme-builder`'s job), and rather than three
//! independent per-role pickers (an earlier version of this component; a
//! single combined choice is what was actually wanted -- one theme,
//! consistently applied to every role at once). `theme-switcher` still never
//! exposes the individual surface/structural tokens (`--background`,
//! `--card`, `--border`, `--radius`, ...) `theme-builder` covers; only the
//! three palette-derived role groups, and only as one linked choice.
//! Classified `EXISTING_DIOXUS_EXTRA` per design.md §7b -- this component
//! has no shadcn/dioxus-components catalog counterpart in
//! `statics/component_compatibility.json`.
//!
//! Each option previews its preset as three overlapping circles -- primary,
//! secondary, and accent's own real colors for that preset -- the same
//! "overlapping swatches" convention modern theme pickers use, sourced from
//! the exact HSL values [`ThemePalette::primary_pairs`]/
//! [`ThemePalette::secondary_pairs`]/[`ThemePalette::accent_pairs`] actually
//! apply, recomputed for whichever appearance (light/dark) is currently
//! resolved so the preview always matches what turning dark mode on or off
//! would actually show. Declares `select` as a `registryDependencies` entry
//! in `registry.json` so installing `theme-switcher` also installs it,
//! matching the existing `mode-toggle -> dropdown-menu` / `date-picker ->
//! calendar, popover` cross-`registry:ui` dependency precedent.
//!
//! **The selected preset is persisted**, through
//! [`adico_primitives::persisted_state::use_persisted_global`] under the
//! `adico-theme-palette` key (`localStorage` on `web`, a small preferences
//! file on `native`) -- the same generic primitive
//! `adico_primitives::theme_mode::use_persisted_theme_mode` itself is built
//! on, so the choice survives a reload the same way the light/dark/system
//! mode already does. The persisted store, not the DOM, is this component's
//! source of truth; every mounted instance (a persistent sidebar picker and
//! this component's own demo page, for example) shares one live selection
//! through the same module-level [`PALETTE`] `GlobalSignal`
//! `use_persisted_global` drives, so changing it in one place updates every
//! other mounted instance immediately, with no reload needed to notice.
//!
//! An earlier version instead read the live `--primary`/`--secondary`/
//! `--accent` values back off the document root once on mount and
//! reverse-matched them against the preset tables. That only ever recovered
//! a value already applied *in the same page session* -- a reload discards
//! it -- so it bought nothing a persisted store doesn't do strictly better,
//! and it's gone now.
//!
//! **A protection was deliberately dropped along with it.** The old
//! read-back was gated behind a one-shot `hydrated` flag specifically so
//! this component would *adopt* a still-mounted sibling editor's live colors
//! rather than stomp them. The apply effect below now writes the persisted
//! preset's inline properties immediately on every mount, so mounting a
//! `ThemeSwitcher` while a `theme-builder` has live per-token edits applied
//! overwrites the primary/secondary/accent subset of those edits. This is
//! the accepted trade, not a new regression: the direction that actually
//! matters -- `theme-builder` reading back whatever `theme-switcher` last
//! applied -- is unaffected and still works via `theme-builder`'s own,
//! separate DOM read-back; and a `theme-builder` edit is explicitly
//! transient (it has its own `use_drop` cleanup on unmount) while a
//! `theme-switcher` preset is a persisted, durable user setting.
//!
//! Accepted limitation, inherited from `use_persisted_global`: on `web` the
//! stored preset loads asynchronously after first mount, so a reload
//! briefly applies the default Slate before the persisted preset lands --
//! strictly better than the previous behavior, which lost the selection
//! entirely on every reload.
//!
//! Writes only the raw `--foo` custom properties, never the `--color-foo`
//! Tailwind aliases the installed `@theme` block already derives from them
//! live via `var()`. An earlier version also wrote `--color-primary`
//! inline, which freezes that alias at a static value and stops it tracking
//! further `--primary` changes -- the same defect fixed in `theme-builder`;
//! see that file's module doc comment and `theme_mode.rs`'s
//! `read_root_properties` doc comment for the full story.
//!
//! `SelectList` is given an explicit `w-56`, not `w-full`: the list is
//! `position: fixed` (`Positioner`'s own placement mechanism), so its
//! containing block is the viewport, not the trigger -- `w-full` there
//! resolved to 100% of the *viewport* width, not the trigger's width,
//! making the palette dropdown visually span the whole screen. Found live
//! via a screenshot; confirmed by reading the popup's own computed
//! `position: fixed; left: 8px;` (the 8px collision-padding floor, not a
//! position relative to the trigger) and measured `width: 1280` matching
//! the viewport exactly. Every other `Select` consumer in this registry
//! already uses a fixed width on its own `SelectList` for the same reason.

use dioxus::prelude::*;

use adico_primitives::persisted_state::use_persisted_global;
use adico_primitives::theme_mode::{
    ResolvedTheme, apply_root_properties, use_persisted_theme_mode,
};

use super::select::{Select, SelectList, SelectOption, SelectTrigger, SelectValue};
use crate::adico_lib::cn::cn;

/// A coordinated palette preset applied to the primary, secondary, and
/// accent semantic role groups together.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub enum ThemePalette {
    #[default]
    Slate,
    Blue,
    Violet,
    Emerald,
    Rose,
    Amber,
}

impl ThemePalette {
    const ALL: [Self; 6] = [
        Self::Slate,
        Self::Blue,
        Self::Violet,
        Self::Emerald,
        Self::Rose,
        Self::Amber,
    ];

    const fn label(self) -> &'static str {
        match self {
            Self::Slate => "Slate",
            Self::Blue => "Blue",
            Self::Violet => "Violet",
            Self::Emerald => "Emerald",
            Self::Rose => "Rose",
            Self::Amber => "Amber",
        }
    }

    /// The short, lowercase persistence token for this preset, matching
    /// `ThemeMode`'s own `"light"`/`"dark"`/`"system"` token convention --
    /// deliberately not derived from [`Self::label`] (whose casing is a
    /// display concern), so a future label-text change can never silently
    /// change the persisted storage format.
    const fn token(self) -> &'static str {
        match self {
            Self::Slate => "slate",
            Self::Blue => "blue",
            Self::Violet => "violet",
            Self::Emerald => "emerald",
            Self::Rose => "rose",
            Self::Amber => "amber",
        }
    }

    fn from_token(token: &str) -> Option<Self> {
        Self::ALL
            .into_iter()
            .find(|candidate| candidate.token() == token)
    }

    /// `(--primary, --primary-foreground)` HSL pair, matching
    /// `theme-builder`'s `Palette::primary_tokens` table exactly.
    const fn primary_hsl(self, dark: bool) -> (&'static str, &'static str) {
        match (self, dark) {
            (Self::Slate, false) => ("222.2 47.4% 11.2%", "210 40% 98%"),
            (Self::Slate, true) => ("210 40% 98%", "222.2 47.4% 11.2%"),
            (Self::Blue, false) => ("221.2 83.2% 53.3%", "210 40% 98%"),
            (Self::Blue, true) => ("213.1 93.9% 67.8%", "222.2 47.4% 11.2%"),
            (Self::Violet, false) => ("262.1 83.3% 57.8%", "210 40% 98%"),
            (Self::Violet, true) => ("263.4 70% 50.4%", "0 0% 100%"),
            (Self::Emerald, false) => ("160.1 84.1% 39.4%", "210 40% 98%"),
            (Self::Emerald, true) => ("158.1 64.4% 51.6%", "2.7 19.3% 10.2%"),
            (Self::Rose, false) => ("346.8 77.2% 49.8%", "210 40% 98%"),
            (Self::Rose, true) => ("349.7 89.2% 60.2%", "0 0% 100%"),
            (Self::Amber, false) => ("37.7 92.1% 50.2%", "26 83.3% 14.1%"),
            (Self::Amber, true) => ("47.9 95.8% 53.1%", "26 83.3% 14.1%"),
        }
    }

    /// `(background, foreground)` HSL pair for a pastel "surface" role --
    /// shared by the semantic `--secondary`/`--muted` role group and the
    /// `--accent`/`--sidebar-accent` role group, matching `theme-builder`'s
    /// `Palette::surface_tokens` table exactly.
    const fn surface_hsl(self, dark: bool) -> (&'static str, &'static str) {
        match (self, dark) {
            (Self::Slate, false) => ("210 40% 96.1%", "222.2 47.4% 11.2%"),
            (Self::Slate, true) => ("217.2 32.6% 17.5%", "210 40% 98%"),
            (Self::Blue, false) => ("214.3 94.6% 92.7%", "221.2 83.2% 29.4%"),
            (Self::Blue, true) => ("217.2 32.6% 17.5%", "219.4 100% 92%"),
            (Self::Violet, false) => ("250 100% 95.3%", "262.1 83.3% 30%"),
            (Self::Violet, true) => ("263.4 38.6% 17.8%", "250 100% 92%"),
            (Self::Emerald, false) => ("152.4 76% 92.2%", "161.4 93.5% 16.9%"),
            (Self::Emerald, true) => ("163.1 36.7% 16.1%", "149.3 80.4% 90%"),
            (Self::Rose, false) => ("355.6 100% 94.7%", "343.4 79.7% 25.7%"),
            (Self::Rose, true) => ("343.4 43.8% 16.1%", "355.6 100% 94.7%"),
            (Self::Amber, false) => ("48 96.5% 88.8%", "26 83.3% 14.1%"),
            (Self::Amber, true) => ("30 47.8% 16.1%", "48 96.5% 88.8%"),
        }
    }

    /// The raw property/value pairs this preset contributes when applied to
    /// the `--primary` role group (including `--ring` and the sidebar
    /// counterparts, matching `theme-builder`'s `set_primary_palette`).
    fn primary_pairs(self, dark: bool) -> [(&'static str, String); 6] {
        let (primary, primary_foreground) = self.primary_hsl(dark);
        [
            ("--primary", primary.to_string()),
            ("--primary-foreground", primary_foreground.to_string()),
            ("--ring", primary.to_string()),
            ("--sidebar-primary", primary.to_string()),
            (
                "--sidebar-primary-foreground",
                primary_foreground.to_string(),
            ),
            ("--sidebar-ring", primary.to_string()),
        ]
    }

    /// The raw property/value pairs this preset contributes when applied to
    /// the `--secondary`/`--muted` role group (matching `theme-builder`'s
    /// `set_secondary_palette`).
    fn secondary_pairs(self, dark: bool) -> [(&'static str, String); 4] {
        let (background, foreground) = self.surface_hsl(dark);
        [
            ("--secondary", background.to_string()),
            ("--secondary-foreground", foreground.to_string()),
            ("--muted", background.to_string()),
            ("--muted-foreground", foreground.to_string()),
        ]
    }

    /// The raw property/value pairs this preset contributes when applied to
    /// the `--accent`/`--sidebar-accent` role group (matching
    /// `theme-builder`'s `set_accent_palette`).
    fn accent_pairs(self, dark: bool) -> [(&'static str, String); 4] {
        let (background, foreground) = self.surface_hsl(dark);
        [
            ("--accent", background.to_string()),
            ("--accent-foreground", foreground.to_string()),
            ("--sidebar-accent", background.to_string()),
            ("--sidebar-accent-foreground", foreground.to_string()),
        ]
    }
}

/// Distinct from `theme-mode`'s own `adico-theme-mode` key: the appearance
/// (light/dark/system) and the palette preset are two independent settings a
/// consumer sets separately, and both need to survive a reload on their own.
const PALETTE_STORAGE_KEY: &str = "adico-theme-palette";

/// The single coordinated preset every mounted `ThemeSwitcher` shares. A
/// `GlobalSignal` (matching `theme_mode.rs`'s own `MODE` convention) rather
/// than a per-mount `use_signal`, so a persistent sidebar instance and this
/// component's own demo-page instance -- or any two simultaneously-mounted
/// instances -- read and drive the same live selection instead of silently
/// diverging. Driven exclusively through
/// `adico_primitives::persisted_state::use_persisted_global` inside
/// [`ThemeSwitcher`] -- never write it directly (`*PALETTE.write() = ...`)
/// anywhere else, or the UI updates but the choice silently stops
/// persisting.
static PALETTE: GlobalSignal<ThemePalette> = Global::new(ThemePalette::default);

/// A single combined palette picker: one [`Select`] whose 6 options each set
/// the primary, secondary, and accent role groups together as one
/// coordinated preset. Applies the selected preset's role variables
/// immediately and re-applies them whenever the resolved light/dark
/// appearance changes (via the shared `theme_mode` signal), so a mode switch
/// and a palette switch compose correctly.
///
/// Deliberately has no `radius` prop: the `rounded-full` swatches are
/// per-preset color-swatch dots rendered in a loop -- circular is the
/// established convention for a selectable color dot (same reasoning as
/// `Skeleton`'s `Circle` variant), not a cosmetic choice.
///
/// `show_label` defaults to `true` (the visible "Theme" caption above the
/// select, as demoed on this component's own page); a caller placing this
/// next to other already-labeled controls -- e.g. a sidebar footer row
/// beside `ModeToggle` -- can pass `false` to drop the redundant caption.
/// Safe to hide purely visually: `SelectTrigger`'s own `aria_label` already
/// names the control for assistive tech independently of this text, so
/// `show_label: false` omits the caption outright rather than merely
/// visually hiding it.
#[component]
pub fn ThemeSwitcher(class: Option<String>, #[props(default = true)] show_label: bool) -> Element {
    let (mode, _set_mode) = use_persisted_theme_mode();
    let (palette, set_palette) = use_persisted_global(
        &PALETTE,
        PALETTE_STORAGE_KEY,
        ThemePalette::token,
        ThemePalette::from_token,
    );

    // Reads `mode()` and `palette()` *inside* the effect body (not as
    // captured plain values) so Dioxus's reactive tracking re-runs this on
    // either a mode change or a palette change -- the exact convention
    // `theme_mode.rs`'s own `apply_resolved_class` doc comment warns about:
    // an earlier version that passed the resolved value in as a plain
    // argument compiled and rendered fine but silently stopped re-applying
    // after first mount.
    use_effect(move || {
        let dark = mode().resolve() == ResolvedTheme::Dark;
        let current = palette();
        let mut pairs = Vec::new();
        pairs.extend(current.primary_pairs(dark));
        pairs.extend(current.secondary_pairs(dark));
        pairs.extend(current.accent_pairs(dark));
        apply_root_properties(&pairs);
    });

    let dark = mode().resolve() == ResolvedTheme::Dark;
    let value = use_memo(move || Some(palette()));

    rsx! {
        label {
            class: cn(&[
                "grid gap-1 text-xs font-medium text-muted-foreground",
                class.as_deref().unwrap_or_default(),
            ]),
            if show_label {
                "Theme"
            }
            Select::<ThemePalette> {
                value: ReadSignal::from(value),
                on_value_change: move |next: Option<ThemePalette>| {
                    set_palette.call(next.unwrap_or_default())
                },
                SelectTrigger { class: "w-full", aria_label: "Theme palette",
                    div { class: "flex flex-1 items-center gap-2",
                        PaletteSwatch { palette: palette(), dark }
                        SelectValue { placeholder: "Choose a theme" }
                    }
                }
                SelectList { class: "w-56", aria_label: "Theme palette options",
                    for (index , option) in ThemePalette::ALL.into_iter().enumerate() {
                        SelectOption::<ThemePalette> {
                            index,
                            value: option,
                            text_value: option.label(),
                            div { class: "flex items-center gap-2",
                                PaletteSwatch { palette: option, dark }
                                span { "{option.label()}" }
                            }
                        }
                    }
                }
            }
        }
    }
}

/// Three small overlapping circles previewing one preset's primary,
/// secondary, and accent colors together -- the "overlapping swatches"
/// convention modern theme pickers use for a coordinated preview. The
/// secondary and accent circles both source from [`ThemePalette::surface_hsl`]
/// (that table's own background and foreground halves, respectively) since
/// `theme-builder`'s underlying data model gives those two role groups the
/// same pastel pair rather than two independent lookup tables -- this is a
/// faithful preview of what actually gets applied, not an approximation.
#[component]
fn PaletteSwatch(palette: ThemePalette, dark: bool) -> Element {
    let (primary, _) = palette.primary_hsl(dark);
    let (secondary, accent) = palette.surface_hsl(dark);
    let primary_style = format!("background-color: hsl({primary});");
    let secondary_style = format!("background-color: hsl({secondary});");
    let accent_style = format!("background-color: hsl({accent});");
    rsx! {
        span {
            class: "relative inline-flex h-5 w-10 shrink-0 items-center",
            "aria-hidden": "true",
            span {
                class: "absolute left-0 size-4 rounded-full ring-2 ring-background",
                style: "{primary_style}",
            }
            span {
                class: "absolute left-3 size-4 rounded-full ring-2 ring-background",
                style: "{secondary_style}",
            }
            span {
                class: "absolute left-6 size-4 rounded-full ring-2 ring-background",
                style: "{accent_style}",
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_palette_has_a_distinct_label() {
        let labels: Vec<_> = ThemePalette::ALL.iter().map(|p| p.label()).collect();
        for (index, label) in labels.iter().enumerate() {
            assert!(!labels[index + 1..].contains(label));
        }
    }

    #[test]
    fn light_and_dark_primary_pairs_differ() {
        for palette in ThemePalette::ALL {
            assert_ne!(palette.primary_hsl(false), palette.primary_hsl(true));
        }
    }

    #[test]
    fn light_and_dark_surface_pairs_differ() {
        for palette in ThemePalette::ALL {
            assert_ne!(palette.surface_hsl(false), palette.surface_hsl(true));
        }
    }

    #[test]
    fn every_palette_has_a_distinct_primary_and_surface_pair_per_appearance() {
        for dark in [false, true] {
            let primaries: Vec<_> = ThemePalette::ALL
                .iter()
                .map(|p| p.primary_hsl(dark))
                .collect();
            let surfaces: Vec<_> = ThemePalette::ALL
                .iter()
                .map(|p| p.surface_hsl(dark))
                .collect();
            for index in 0..primaries.len() {
                assert!(!primaries[index + 1..].contains(&primaries[index]));
                assert!(!surfaces[index + 1..].contains(&surfaces[index]));
            }
        }
    }

    #[test]
    fn palette_tokens_round_trip_every_preset() {
        for palette in ThemePalette::ALL {
            assert_eq!(ThemePalette::from_token(palette.token()), Some(palette));
        }
    }

    #[test]
    fn palette_tokens_are_distinct_lowercase_ascii() {
        let tokens: Vec<_> = ThemePalette::ALL.iter().map(|p| p.token()).collect();
        for (index, token) in tokens.iter().enumerate() {
            assert!(!tokens[index + 1..].contains(token));
            assert!(token.chars().all(|c| c.is_ascii_lowercase()));
        }
    }

    #[test]
    fn from_token_rejects_an_unrecognized_token() {
        // Locks in that persisted tokens are the lowercase form (`token()`,
        // not `label()`), so a future label-text change can't silently
        // change the persisted storage format.
        assert_eq!(ThemePalette::from_token(""), None);
        assert_eq!(ThemePalette::from_token("slat"), None);
        assert_eq!(ThemePalette::from_token("Slate"), None);
    }

    #[test]
    fn the_three_role_groups_apply_fourteen_distinct_properties() {
        let dark = false;
        let palette = ThemePalette::default();
        let mut names: Vec<&str> = Vec::new();
        names.extend(palette.primary_pairs(dark).map(|(name, _)| name));
        names.extend(palette.secondary_pairs(dark).map(|(name, _)| name));
        names.extend(palette.accent_pairs(dark).map(|(name, _)| name));
        assert_eq!(names.len(), 14);
        for (index, name) in names.iter().enumerate() {
            assert!(
                !names[index + 1..].contains(name),
                "{name} written by more than one role group"
            );
        }
    }
}

//! Styled Time Picker roots composed from adico's owned time/popover
//! primitives. The primitives keep segment editing, focus, and ARIA
//! behavior; the roots supply the semantic layout hook. Mirrors
//! `registry/ui/date_picker.rs`'s composition shape throughout -- see that
//! file for the established conventions this one follows.

use dioxus::html::geometry::ElementPoint;
use dioxus::prelude::*;
use time::Time;

use super::native_select::{NativeSelect, NativeSelectOption, NativeSelectSize};
use super::popover::{PopoverContent, PopoverTrigger};
use crate::adico_lib::cn::cn;
use crate::adico_lib::variants::Radius;
use adico_primitives::icons::ChevronDown;
use adico_primitives::popover::{PopoverRoot, PopoverRootProps};
use adico_primitives::scroll_area::scroll_area_visibility_class;
use adico_primitives::time_picker::{
    TimePicker as PrimitiveTimePicker, TimePickerInputValue as PrimitiveTimePickerInputValue,
    format_time, from_display_hour, to_display_hour,
};

pub use adico_primitives::time_picker::{
    TimePickerContext, TimePickerHourSegment, TimePickerMeridiemSegment, TimePickerMinuteSegment,
    TimePickerSecondSegment,
};

/// Which popup body view a [`TimePicker`] shows -- independent of `is_12h`
/// (12h/24h format is a value-formatting concern; this is purely which
/// registry-level part renders). Registry-only: no primitive behavior
/// depends on it, only whether [`TimePickerBody`] renders
/// [`TimePickerColumns`] or [`TimePickerClock`]. `TimePickerColumns` and
/// `TimePickerClock` both remain independently composable directly (as
/// `time-picker`'s own demo page does, showing both at once) for a consumer
/// who wants to hardcode one specific view without a prop switch.
#[derive(Clone, Copy, PartialEq, Eq, Default)]
pub enum TimePickerView {
    #[default]
    Digital,
    Analog,
}

/// A registry-only context so [`TimePickerBody`] can read the enclosing
/// [`TimePicker`]'s `view` prop without it being threaded through every
/// intermediate layer by hand.
#[derive(Clone, Copy)]
struct TimePickerViewContext {
    view: ReadSignal<TimePickerView>,
}

/// Props for the styled time picker root.
#[derive(Props, Clone, PartialEq)]
pub struct TimePickerProps {
    #[props(default)]
    pub on_value_change: Callback<Option<Time>>,
    #[props(default)]
    pub selected_time: ReadSignal<Option<Time>>,
    #[props(default)]
    pub disabled: ReadSignal<bool>,
    #[props(default = ReadSignal::new(Signal::new(false)))]
    pub read_only: ReadSignal<bool>,
    #[props(default = ReadSignal::new(Signal::new(false)))]
    pub is_12h: ReadSignal<bool>,
    #[props(default = ReadSignal::new(Signal::new(false)))]
    pub show_seconds: ReadSignal<bool>,
    #[props(default = ReadSignal::new(Signal::new(false)))]
    pub roving_loop: ReadSignal<bool>,
    /// Which popup body [`TimePickerBody`] renders -- see [`TimePickerView`].
    #[props(default = ReadSignal::new(Signal::new(TimePickerView::Digital)))]
    pub view: ReadSignal<TimePickerView>,
    #[props(default)]
    pub class: Option<String>,
    #[props(extends = GlobalAttributes)]
    #[props(extends = div)]
    pub attributes: Vec<Attribute>,
    pub children: Element,
}

/// A styled time picker retaining the primitive's full interaction API.
#[component]
pub fn TimePicker(props: TimePickerProps) -> Element {
    use_context_provider(|| TimePickerViewContext { view: props.view });
    let class = cn(&[
        "relative inline-block",
        props.class.as_deref().unwrap_or_default(),
    ]);
    rsx! {
        PrimitiveTimePicker {
            on_value_change: props.on_value_change,
            selected_time: props.selected_time,
            disabled: props.disabled,
            read_only: props.read_only,
            is_12h: props.is_12h,
            show_seconds: props.show_seconds,
            roving_loop: props.roving_loop,
            class,
            attributes: props.attributes,
            {props.children}
        }
    }
}

#[allow(unpredictable_function_pointer_comparisons)]
#[derive(Props, Clone, PartialEq)]
pub struct TimePickerPopoverProps {
    #[props(default = ReadSignal::new(Signal::new(true)))]
    pub is_modal: ReadSignal<bool>,
    pub open: ReadSignal<Option<bool>>,
    #[props(default)]
    pub default_open: bool,
    #[props(default)]
    pub on_open_change: Callback<bool>,
    #[props(default)]
    pub class: Option<String>,
    #[props(extends = GlobalAttributes)]
    pub attributes: Vec<Attribute>,
    pub children: Element,
    #[props(default = PopoverRoot)]
    pub popover_root: fn(PopoverRootProps) -> Element,
}

/// Styled popover root for composing [`TimePickerTrigger`] and
/// [`TimePickerContent`] around a [`TimePicker`]. Takes the same
/// `popover_root` injection prop as `date-picker`'s `DatePickerPopover` and
/// `color-picker`'s `ColorPickerPopover`.
#[component]
pub fn TimePickerPopover(props: TimePickerPopoverProps) -> Element {
    let class = cn(&[
        "group/time-picker",
        props.class.as_deref().unwrap_or_default(),
    ]);
    let PopoverRoot = props.popover_root;
    rsx! {
        PopoverRoot {
            is_modal: props.is_modal,
            open: props.open,
            default_open: props.default_open,
            on_open_change: props.on_open_change,
            class,
            attributes: props.attributes,
            {props.children}
        }
    }
}

#[derive(Props, Clone, PartialEq)]
pub struct TimePickerTriggerProps {
    /// Renders a compact icon-only disclosure button (the same shape
    /// `date-picker`'s `DatePickerTrigger` always uses) instead of the
    /// default labeled button that spells out the formatted time.
    ///
    /// Set this whenever the trigger sits *inside* a [`TimePickerInput`]
    /// alongside [`TimePickerInputValue`]: that field already displays the
    /// value, so the default labeled trigger renders the same time a second
    /// time, inside its own nested bordered box (e.g. `05 : 00` followed by
    /// `5:00 AM ⌄`). The labeled default remains correct for a standalone
    /// trigger with no separate input, which is how `date-time-picker`'s own
    /// `DateTimePickerTrigger` presents itself.
    #[props(default)]
    pub compact: bool,
    #[props(default)]
    pub class: Option<String>,
    #[props(extends = GlobalAttributes)]
    #[props(extends = button)]
    pub attributes: Vec<Attribute>,
    #[props(default)]
    pub children: Option<Element>,
}

/// Disclosure trigger composed from the installed Popover façade. Defaults
/// to showing the currently selected time (via [`TimePickerContext`]) --
/// falling back to "Pick a time" -- so activating this trigger both opens
/// the picker and shows the time it currently holds. Pass `compact: true`
/// when composing it inside a [`TimePickerInput`], which already shows the
/// value (see [`TimePickerTriggerProps::compact`]). Must be used inside a
/// [`TimePicker`] (for the context) and a [`TimePickerPopover`].
#[component]
pub fn TimePickerTrigger(props: TimePickerTriggerProps) -> Element {
    let ctx = use_context::<TimePickerContext>();
    let label = use_memo(move || match ctx.selected_time() {
        Some(time) => format_time(time, ctx.is_12h(), ctx.show_seconds()),
        None => "Pick a time".to_string(),
    });
    // Swaps the whole base class rather than layering overrides on top of
    // it: `cn` concatenates without resolving Tailwind conflicts, so a
    // caller-supplied `border-0`/`px-0` would not reliably beat the base
    // `border`/`px-3` (which utility wins is decided by stylesheet order).
    let class = cn(&[
        if props.compact {
            "ml-1 size-6 rounded-sm text-muted-foreground transition-colors hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
        } else {
            "inline-flex h-9 items-center gap-2 rounded-md border border-input bg-background px-3 text-sm shadow-xs transition-colors hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50"
        },
        props.class.as_deref().unwrap_or_default(),
    ]);
    let children = props.children.unwrap_or_else(|| {
        if props.compact {
            rsx! {
                ChevronDown {
                    class: "size-4 shrink-0 transition-transform duration-200 group-data-[state=open]/time-picker:rotate-180",
                    size: 16,
                }
                span { class: "sr-only", "Toggle time picker" }
            }
        } else {
            rsx! {
                "{label()}"
                ChevronDown {
                    class: "size-4 shrink-0 text-muted-foreground transition-transform duration-200 group-data-[state=open]/time-picker:rotate-180",
                    size: 16,
                }
            }
        }
    });
    rsx! {
        PopoverTrigger { class, attributes: props.attributes, {children} }
    }
}

