//! Source-owned shadcn-style Toggle for Dioxus, backed by the owned adico
//! primitive layer.

use dioxus::prelude::*;

use adico_primitives::toggle::Toggle as TogglePrimitive;

use crate::adico_lib::cn::cn;
use crate::adico_lib::variants::Radius;

/// The visual size of a [`Toggle`].
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum ToggleSize {
    /// Compact size.
    Sm,
    /// Default size.
    #[default]
    Default,
    /// Larger size.
    Lg,
}

impl ToggleSize {
    fn class(self) -> &'static str {
        match self {
            Self::Sm => "h-8 px-1.5 min-w-8",
            Self::Default => "h-9 px-2 min-w-9",
            Self::Lg => "h-10 px-2.5 min-w-10",
        }
    }
}

/// The visual treatment of a [`Toggle`]. Upstream shadcn's `toggleVariants`
/// has always had this axis; adico's `Toggle` was missing it entirely until
/// now (task 5.2) -- a real lost capability, not a styling nuance, since
/// there was previously no way to render an outlined toggle at all.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum ToggleVariant {
    /// Transparent background, the existing default look.
    #[default]
    Default,
    /// Bordered neutral styling, matching `Button`'s own `Outline` variant.
    Outline,
}

impl ToggleVariant {
    fn class(self) -> &'static str {
        match self {
            Self::Default => "bg-transparent",
            Self::Outline => {
                "border border-input bg-transparent shadow-xs hover:bg-accent hover:text-accent-foreground"
            }
        }
    }
}

/// Props for [`Toggle`].
#[derive(Props, Clone, PartialEq)]
pub struct ToggleProps {
    /// The controlled pressed state of the toggle.
    #[props(default)]
    pub pressed: ReadSignal<Option<bool>>,
    /// The default pressed state when uncontrolled.
    #[props(default)]
    pub default_pressed: bool,
    /// Whether the toggle is disabled.
    #[props(default)]
    pub disabled: ReadSignal<bool>,
    /// The visual size.
    #[props(default)]
    pub size: ToggleSize,
    /// The visual treatment.
    #[props(default)]
    pub variant: ToggleVariant,
    /// Callback fired when the pressed state changes.
    #[props(default)]
    pub on_pressed_change: Callback<bool>,
    /// Extra classes appended to the semantic default.
    #[props(default)]
    pub class: Option<String>,
    /// Callback fired when the toggle is mounted.
    #[props(default)]
    pub onmounted: Callback<Event<MountedData>>,
    /// Callback fired when the toggle receives focus.
    #[props(default)]
    pub onfocus: Callback<Event<FocusData>>,
    /// Callback fired when a key is pressed on the toggle.
    #[props(default)]
    pub onkeydown: Callback<Event<KeyboardData>>,
    /// Corner radius of the toggle surface.
    #[props(default = Radius::Md)]
    pub radius: Radius,
    /// Native button/global attributes and events.
    #[props(extends = GlobalAttributes)]
    #[props(extends = button)]
    pub attributes: Vec<Attribute>,
    /// Caller-composed toggle content.
    pub children: Element,
}

/// A two-state pressable button with the default adico/shadcn visual
/// language.
#[component]
pub fn Toggle(props: ToggleProps) -> Element {
    let class = cn(&[
        "inline-flex items-center justify-center gap-2 text-sm font-medium outline-none transition-colors \
         hover:bg-muted hover:text-muted-foreground \
         focus-visible:ring-2 focus-visible:ring-ring/50 \
         disabled:pointer-events-none disabled:opacity-50 \
         data-[state=on]:bg-accent data-[state=on]:text-accent-foreground",
        props.variant.class(),
        props.size.class(),
        props.radius.class(),
        props.class.as_deref().unwrap_or_default(),
    ]);
    rsx! {
        TogglePrimitive {
            pressed: props.pressed,
            default_pressed: props.default_pressed,
            disabled: props.disabled,
            on_pressed_change: props.on_pressed_change,
            onmounted: props.onmounted,
            onfocus: props.onfocus,
            onkeydown: props.onkeydown,
            class,
            attributes: props.attributes,
            {props.children}
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_size_has_a_distinct_class() {
        assert_ne!(ToggleSize::Sm.class(), ToggleSize::Default.class());
        assert_ne!(ToggleSize::Default.class(), ToggleSize::Lg.class());
    }

    #[test]
    fn pressed_state_uses_semantic_accent_surface() {
        let class = cn(&[
            "inline-flex items-center justify-center gap-2 rounded-md text-sm font-medium outline-none transition-colors \
             hover:bg-muted hover:text-muted-foreground \
             focus-visible:ring-2 focus-visible:ring-ring/50 \
             disabled:pointer-events-none disabled:opacity-50 \
             data-[state=on]:bg-accent data-[state=on]:text-accent-foreground",
            "",
        ]);
        assert!(class.contains("data-[state=on]:bg-accent"));
    }
}

//! Source-owned shadcn-style Toggle Group for Dioxus, backed by the owned
//! adico primitive layer.

use std::collections::HashSet;

use dioxus::prelude::*;

use adico_primitives::toggle_group::ToggleGroup as ToggleGroupPrimitive;
use adico_primitives::toggle_group::ToggleItem as ToggleItemPrimitive;

use crate::adico_lib::cn::cn;
use crate::adico_lib::variants::Radius;

/// The row of [`ToggleItem`]s. A styled facade over the primitive's own
/// `ToggleGroup`, which has no default layout class at all (a bare
/// `pub use` re-export previously): each `ToggleItem` is independently
/// rounded independently (this crate doesn't replicate upstream's connected/flush
/// `spacing=0` segmented look), so with nothing spacing them apart the
/// items rendered flush against each other with no visual gap at all --
/// found live (reported directly by the user: "no space in toggle group").
#[component]
pub fn ToggleGroup(
    #[props(default)] default_pressed: HashSet<usize>,
    pressed: ReadSignal<Option<HashSet<usize>>>,
    #[props(default)] on_pressed_change: Callback<HashSet<usize>>,
    #[props(default)] disabled: ReadSignal<bool>,
    #[props(default)] allow_multiple_pressed: ReadSignal<bool>,
    #[props(default)] horizontal: ReadSignal<bool>,
    #[props(default = ReadSignal::new(Signal::new(true)))] roving_loop: ReadSignal<bool>,
    #[props(default)] class: Option<String>,
    #[props(extends = GlobalAttributes)] attributes: Vec<Attribute>,
    children: Element,
) -> Element {
    let class = cn(&[
        // `max-w-full flex-wrap` (R4): items are independent, gapped toggle
        // buttons with no corner-joining between them (unlike
        // `button_group.rs`), so wrapping to a second row is visually safe.
        "flex max-w-full flex-wrap items-center gap-1",
        class.as_deref().unwrap_or_default(),
    ]);
    rsx! {
        ToggleGroupPrimitive {
            default_pressed,
            pressed,
            on_pressed_change,
            disabled,
            allow_multiple_pressed,
            horizontal,
            roving_loop,
            class,
            attributes,
            {children}
        }
    }
}

/// The visual size of a [`ToggleItem`], matching `Toggle`'s own `ToggleSize`
/// values (a small, deliberate duplication -- each registry item stays an
/// independent, source-owned copy rather than taking a cross-item
/// dependency for one shared enum).
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum ToggleItemSize {
    /// Compact size.
    Sm,
    /// Default size.
    #[default]
    Default,
    /// Larger size.
    Lg,
}

impl ToggleItemSize {
    fn class(self) -> &'static str {
        match self {
            Self::Sm => "h-8 px-1.5 min-w-8",
            Self::Default => "h-9 px-2 min-w-9",
            Self::Lg => "h-10 px-2.5 min-w-10",
        }
    }
}

/// The visual treatment of a [`ToggleItem`]. Was entirely absent before
/// task 5.2 -- upstream shadcn's `ToggleGroup` propagates a `variant` to
/// every item via React context; adico has no context-propagation
/// mechanism for this, so each `ToggleItem` takes its own `variant` prop
/// instead (a caller composing a group sets the same variant on every item,
/// same end result, one extra prop per item).
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum ToggleItemVariant {
    /// Transparent background, the existing default look.
    #[default]
    Default,
    /// Bordered neutral styling.
    Outline,
}

impl ToggleItemVariant {
    fn class(self) -> &'static str {
        match self {
            Self::Default => "bg-transparent",
            Self::Outline => {
                "border border-input bg-transparent shadow-xs hover:bg-accent hover:text-accent-foreground"
            }
        }
    }
}

/// A single pressable item within a [`ToggleGroup`].
#[component]
pub fn ToggleItem(
    index: ReadSignal<usize>,
    #[props(default)] disabled: ReadSignal<bool>,
    #[props(default)] size: ToggleItemSize,
    #[props(default)] variant: ToggleItemVariant,
    #[props(default = Radius::Md)] radius: Radius,
    class: Option<String>,
    #[props(extends = GlobalAttributes)] attributes: Vec<Attribute>,
    children: Element,
) -> Element {
    let class = cn(&[
        "inline-flex items-center justify-center gap-2 text-sm font-medium outline-none transition-colors hover:bg-muted hover:text-muted-foreground focus-visible:ring-2 focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 data-[state=on]:bg-accent data-[state=on]:text-accent-foreground",
        variant.class(),
        size.class(),
        radius.class(),
        class.as_deref().unwrap_or_default(),
    ]);
    rsx! {
        ToggleItemPrimitive {
            index,
            disabled,
            class,
            attributes,
            {children}
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn pressed_item_uses_the_same_semantic_accent_surface_as_toggle() {
        let class = cn(&[
            "data-[state=on]:bg-accent data-[state=on]:text-accent-foreground",
            "",
        ]);
        assert!(class.contains("data-[state=on]:bg-accent"));
    }
}

documentation.usage:
ToggleGroup { pressed: pressed(), on_pressed_change: move |v| pressed.set(v),
    ToggleItem { index: 0usize, "Bold" }
}

